 "content": "from copy import deepcopy


def transform(grid):
    """Let each nonzero 4-connected object fall toward the solid 2 boundary."""
    h, w = len(grid), len(grid[0])
    out = deepcopy(grid)
    # Find same-color 4-connected objects; zeros and the 2 boundary are not objects.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    # Move objects in the order nearest the barrier first. Each object translates
    # intact until the next step would hit the boundary or another object.
    upward = any(all(v == 2 for v in row) for row in grid[:1])
    objects.sort(key=lambda obj: min(r for r, c in obj[1]), reverse=not upward)
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = 0
        step = -1 if upward else 1
        shift = 0
        while True:
            nr_cells = [(r + shift + step, c) for r, c in cells]
            if any(nr < 0 or nr >= h or (nr, nc) in occupied for nr, nc in nr_cells):
                break
            shift += step
        moved = [(r + shift, c) for r, c in cells]
        for r, c in moved:
            out[r][c] = color
            occupied.add((r, c))
    return out
